head.script:
scwin.onpageload = function() {

};

scwin.grd1_onviewchange = function(info) {
    if(info.colIndex == 0){
        dataList1.setCellData(info.rowIndex, "col2", "aaaaa");
    }

};

		scwin.simulateWrapper = function(target, type, options) {
			WebSquare.wUnit.getJq(target).simulate(type, options);
		}
		scwin.setSimulate = function() {
			WebSquare.wUnit.getJq('#G_mf_grd1__col1').simulate('key-sequence', {
				sequence: 'a'
			});
		}

		scwin.checkVal = function() {
			return WebSquare.wUnit.getDomById('G_'+$p.id+'grd1__col1').style.display == 'block';
		}
		scwin.unitTest = function() {
			//Unit
			WebSquare.wUnit.start();
			WebSquare.wUnit.addCommand("pause", "500");
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd1_cell_0_0').click()");
			WebSquare.wUnit.addCommand("pause", "400");
			WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
			WebSquare.wUnit.addCommand("pause", "500");
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd1_cell_1_0').click()");
			WebSquare.wUnit.addCommand("pause", "400");			

			WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
			WebSquare.wUnit.addCommand("pause", "500");

			//Run test and stop
			WebSquare.wUnit.run();
			WebSquare.wUnit.stop();
		}	
		scwin.unitTest()
